from PIL import Image

def blobs(path, thresh=50):
    im = Image.open(path)
    w,h = im.size
    px = im.load()
    visited = [[False]*w for _ in range(h)]
    out=[]
    for y in range(h):
        for x in range(w):
            if visited[y][x]:
                continue
            r,g,b = px[x,y][:3]
            if (r+g+b)/3 > thresh:
                continue
            stack=[(x,y)]
            visited[y][x]=True
            pts=[]
            while stack:
                cx,cy=stack.pop()
                pts.append((cx,cy))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=cx+dx,cy+dy
                    if 0<=nx<w and 0<=ny<h and not visited[ny][nx]:
                        r,g,b=px[nx,ny][:3]
                        if (r+g+b)/3 <= thresh:
                            visited[ny][nx]=True
                            stack.append((nx,ny))
            if 30 < len(pts) < 8000:
                xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
                out.append((len(pts), sum(xs)/len(xs), sum(ys)/len(ys)))
    return out

