from PIL import Image

def analyze(path):
    im = Image.open(path)
    w,h=im.size
    px=im.load()
    # gripper edge
    edge=[]
    for x in range(w):
        y=0
        while y<h-1 and sum(px[x,y][:3])/3 >= 40:
            y+=1
        while y<h-1 and sum(px[x,y][:3])/3 < 40:
            y+=1
        edge.append(y)
    # find max protrusion region: edge significantly below a local linear trend
    # The gripper edge is V-shaped or angled. Pin is a local bump.
    # Use second difference or compare to neighbors 25px away
    bumps=[]
    for x in range(30, w-30):
        base = (edge[x-25]+edge[x+25])/2
        if edge[x] > base+6:
            bumps.append((edge[x]-base, x, edge[x]))
    # cluster bumps
    clusters=[]
    for b in bumps:
        if clusters and b[1]-clusters[-1][-1][1] < 8:
            clusters[-1].append(b)
        else:
            clusters.append([b])
    print(path, 'bump clusters:')
    for cl in clusters:
        if max(c[0] for c in cl) < 8:
            continue
        xs=[c[1] for c in cl]
        # weighted
        cx=sum(c[1]*c[0] for c in cl)/sum(c[0] for c in cl)
        cy=sum(c[2]*c[0] for c in cl)/sum(c[0] for c in cl)
        print(f"  bump cx={cx:.1f} cy={cy:.1f} strength={max(c[0] for c in cl):.1f} width={xs[-1]-xs[0]}")

    # dark blobs not connected to top (bores)
    visited=[[False]*w for _ in range(h)]
    blobs=[]
    for y in range(h):
        for x in range(w):
            if visited[y][x]:
                continue
            if sum(px[x,y][:3])/3 > 45:
                continue
            stack=[(x,y)]
            visited[y][x]=True
            pts=[]
            touches_top=False
            while stack:
                cx,cy=stack.pop()
                pts.append((cx,cy))
                if cy<5: touches_top=True
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=cx+dx,cy+dy
                    if 0<=nx<w and 0<=ny<h and not visited[ny][nx] and sum(px[nx,ny][:3])/3<=45:
                        visited[ny][nx]=True
                        stack.append((nx,ny))
            if (not touches_top) and 30<len(pts)<5000:
                xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
                blobs.append((len(pts), sum(xs)/len(xs), sum(ys)/len(ys)))
    print('  blobs', [(round(n), round(x,1), round(y,1)) for n,x,y in blobs])

